// Literature values used when no calibration table is present.
const UNCALIBRATED = { covid: { G: 1, emissionMedian: 0.52 }, flu: { G: 1, emissionMedian: 0.035 }, rsv: { G: 1, emissionMedian: 0.035 } };
// Fields interpolated from the calibration table (when the table has them).
const CALIBRATED_FIELDS = ['G', 'emissionMedian', 'staffDailyHazard', 'visitorInfectiousProb'];

// Interpolated fitted values for a pathogen at a close-range share:
// { G, emissionMedian } and, where fitted (COVID), { staffDailyHazard,
// visitorInfectiousProb }. Log-linear interpolation; clamped to the table.
export function calibrated(pathogen = 'covid', closeShare = 0.5) {
  const tab = CALIBRATION[pathogen] || CALIBRATION.covid;
  const fb = UNCALIBRATED[pathogen] || UNCALIBRATED.covid;
  if (!tab || !tab.length) return { G: fb.G, emissionMedian: fb.emissionMedian };
  const t = tab.slice().sort((a, b) => a.closeShare - b.closeShare);
  const pick = (x) => { const o = {}; for (const k of CALIBRATED_FIELDS) if (x[k] != null) o[k] = x[k]; return o; };
  if (closeShare <= t[0].closeShare) return pick(t[0]);
  if (closeShare >= t[t.length - 1].closeShare) return pick(t[t.length - 1]);
  for (let i = 1; i < t.length; i++) {
    if (closeShare > t[i].closeShare) continue;
    if (closeShare === t[i].closeShare) return pick(t[i]);
    const a = t[i - 1], b = t[i], f = (closeShare - a.closeShare) / (b.closeShare - a.closeShare);
    const o = {};
    for (const k of CALIBRATED_FIELDS) if (a[k] != null && b[k] != null) o[k] = Math.exp(Math.log(a[k]) + f * (Math.log(b[k]) - Math.log(a[k])));
    return o;
  }
  return pick(t[t.length - 1]);
}

