// Parameter metadata shown on the public page. P(path, label, group, units,
// [low, central, high], { source, note, scale, integer, byPathogen }).
// ---------------------------------------------------------------------------
function P(path, label, group, units, v, extra = {}) {
  const e = { path, label, group, units, low: v[0], central: v[1], high: v[2], scale: extra.scale || 'linear', source: extra.source || JUDGMENT, note: extra.note || '' };
  if (extra.integer) e.integer = true;
  if (extra.byPathogen) e.byPathogen = extra.byPathogen;
  if (extra.anchoredOnly) e.anchoredOnly = true;   // set by anchoredConfig, not by defaultConfig
  return e;
}
