const CAL = { covid: calibrated('covid', SHARE.central), flu: calibrated('flu', SHARE.central), rsv: calibrated('rsv', SHARE.central) };
const CAL_LO = { covid: calibrated('covid', SHARE.low), flu: calibrated('flu', SHARE.low), rsv: calibrated('rsv', SHARE.low) };
const CAL_HI = { covid: calibrated('covid', SHARE.high), flu: calibrated('flu', SHARE.high), rsv: calibrated('rsv', SHARE.high) };
// Slider ranges: literature range, widened to include the fitted values at close-range shares 0.2-0.8.
const span = (lit, p, k) => { const xs = [CAL[p][k], CAL_LO[p][k], CAL_HI[p][k]].filter((x) => x != null); const c = CAL[p][k] != null ? CAL[p][k] : lit[1]; return [Math.min(lit[0], ...xs), c, Math.max(lit[2], ...xs)]; };
const emitRange = (p) => span({ covid: [0.36, 0.52, 1.56], flu: [0.012, 0.035, 0.105], rsv: [0.012, 0.035, 0.105] }[p], p, 'emissionMedian');
const gRange = (p) => span([CAL_LO[p].G, CAL[p].G, CAL_HI[p].G], p, 'G');
const hazRange = (p) => span([0.0002, 0.001, 0.003], p, 'staffDailyHazard');
const visRange = (p) => span([0.001, 0.006, 0.02], p, 'visitorInfectiousProb');
const rng3 = (r, extra = {}) => ({ low: r[0], central: r[1], high: r[2], ...extra });
// Exposure cap on added air changes = 3.6 × susceptibility × room-average UV (µW/cm²).
const NV = ' Not validated: the influenza and RSV settings have not been fitted to data the model can reproduce.';

// How easily far-UVC inactivates a virus in air: Illuminate's low, median and high for the species (see ILLUMINATE.k).
const kRange = (pathogen) => { const K = ILLUMINATE.k[pathogen]; return [K.low, K.central, K.high]; };
const rng = ([low, central, high]) => ({ low, central, high });
const kList = (rows) => rows.map((r) => `${r.k}${r.strain ? ' for ' + r.strain.replace(/\s*\(.*\)/, '').replace(/^HCOV-?\s*/i, 'HCoV-') : ''} (${r.ref})`).join('; ');
function kNote(pathogen) {
  const K = ILLUMINATE.k[pathogen], n = K.rows.length;
  const lead = pathogen === 'covid'
    ? `Illuminate's table of published constants holds ${n} measurements for human coronaviruses in air at 222 nm. The model takes their median, with the lowest and highest as the ends of the range; this is the rule Illuminate applies to a reference organism. `
    : `Illuminate's table of published constants holds ${n} measurements for influenza virus in air at 222 nm, ${Math.round(K.high / K.low)}-fold apart. The model takes their median, which for ${n === 2 ? 'two' : n} values is the midpoint, with the two measurements as the ends of the range. `;
  const tail = pathogen === 'covid'
    ? ' Only the lowest was made on SARS-CoV-2 itself. The highest is OSLUV\'s own reanalysis of the Welch data and has not been published. A 2025 study of SARS-CoV-2 that is not yet in the table reports 4.4 at 40% humidity and 6.8 at 65% (Angel et al. 2025).'
    : '';
  return lead + 'In order: ' + kList(K.rows) + '.' + tail;
}
