// ---------------------------------------------------------------------------
// Small path helpers (also used by analysis.js and cli.js).
// ---------------------------------------------------------------------------
export function getPath(obj, path) {
  let o = obj;
  for (const k of path.split('.')) { if (o == null) return undefined; o = o[k]; }
  return o;
}
export function setPath(obj, path, value) {
  const ks = path.split('.');
  let o = obj;
  for (let i = 0; i < ks.length - 1; i++) {
    if (o[ks[i]] == null || typeof o[ks[i]] !== 'object') o[ks[i]] = {};
    o = o[ks[i]];
  }
  o[ks[ks.length - 1]] = value;
}
function cloneJSON(x) { return JSON.parse(JSON.stringify(x)); }
// Deep-merge plain objects (arrays and scalars in `over` replace those in `base`).
export function mergeConfig(base, over) {
  const out = cloneJSON(base);
  (function rec(dst, src) {
    for (const k of Object.keys(src || {})) {
      const v = src[k];
      if (v && typeof v === 'object' && !Array.isArray(v) && dst[k] && typeof dst[k] === 'object' && !Array.isArray(dst[k])) rec(dst[k], v);
      else dst[k] = cloneJSON(v);
    }
  })(out, over);
  return out;
}

// Pathogen presets, as nested config overrides built from the byPathogen
// values above (single source of truth).
function buildPathogenPresets() {
  const labels = { covid: 'COVID-19', flu: 'Influenza', rsv: 'RSV' };
  const out = {};
  for (const name of Object.keys(labels)) {
    const overrides = { pathogen: name };
    if (name !== 'covid') for (const p of PARAMS) if (p.byPathogen && p.byPathogen[name] && !p.anchoredOnly) setPath(overrides, p.path, p.byPathogen[name].central);
    out[name] = { label: labels[name], overrides };
  }
  return out;
}
export const PATHOGENS = buildPathogenPresets();

// Full config for a pathogen: BASE + central values + pathogen overrides.
// Unknown pathogen names (e.g. 'custom') fall back to covid values.
export function defaultConfig(pathogen = 'covid') {
  const cfg = cloneJSON(BASE);
  for (const p of PARAMS) if (!p.anchoredOnly) setPath(cfg, p.path, p.central);   // anchored-only inputs belong to anchoredConfig; the engine's own default (random arrivals) is left alone
  const preset = PATHOGENS[pathogen] || PATHOGENS.covid;
  const out = mergeConfig(cfg, preset.overrides);
  out.pathogen = pathogen;
  // For display only (the engine works it out per room): clean air one lamp
  // delivers in a 2.4 m-high room, before the real-world factor.
  out.lamp.ecadr = lampCadrAt(out.lamp, 2.4);
  return out;
}
// Per-lamp clean air (m³/h) at a ceiling height, as the engine computes it.
export function lampCadrAt(lamp, height) {
  const t = lamp.mountingTable;
  let f = 1;
  if (lamp.followMountingRule === 1 || lamp.followMountingRule === true) {
    if (height <= t[0][0]) f = t[0][1];
    else if (height >= t[t.length - 1][0]) f = t[t.length - 1][1];
    else for (let i = 1; i < t.length; i++) if (height <= t[i][0]) { f = t[i - 1][1] + (t[i][1] - t[i - 1][1]) * (height - t[i - 1][0]) / (t[i][0] - t[i - 1][0]); break; }
  }
  return 0.36 * lamp.susceptibility * lamp.outputMw * f * height * lamp.pathFactor;
}

// Range of a parameter for a pathogen: {low, central, high}.
export function paramRange(param, pathogen = 'covid') {
  const b = param.byPathogen && param.byPathogen[pathogen];
  return b ? { low: b.low, central: b.central, high: b.high } : { low: param.low, central: param.central, high: param.high };
}

