// Fitted and implied values at an out-of-reach share: { G, emissionMedian, trueAR, staffAR, reportShare }.
// reportShare = share of resident infections that must be reported for the model to agree with the
// surveillance figure (1 when the model infects fewer).
export function anchoredAt(closeShare, pathogen = 'covid') {
  const A = ANCHORS[pathogen] || ANCHORED, t = A.table, s = Math.max(t[0].closeShare, Math.min(t[t.length - 1].closeShare, closeShare));
  let i = 1; while (i < t.length - 1 && s > t[i].closeShare) i++;
  const a = t[i - 1], b = t[i], f = (s - a.closeShare) / (b.closeShare - a.closeShare), lin = (k) => a[k] + f * (b[k] - a[k]), geo = (k) => Math.exp(Math.log(a[k]) + f * (Math.log(b[k]) - Math.log(a[k])));
  const trueAR = lin('trueAR');
  return { G: geo('G'), emissionMedian: a.emissionMedian != null ? geo('emissionMedian') : A.emissionMedian, trueAR, staffAR: lin('staffAR'), reportShare: Math.min(1, A.reportedAR / trueAR) };
}
export function anchoredConfig(closeShare, pathogen = 'covid') {
  const A = ANCHORS[pathogen] || ANCHORED; if (closeShare == null) closeShare = A.shares.central;
  const c = defaultConfig(ANCHORS[pathogen] ? pathogen : 'covid'), at = anchoredAt(closeShare, pathogen);
  c.importation.arrivalEveryDays = A.arrivalEveryDays; c.importation.visitorInfectiousProb = 0;
  c.emission.median = at.emissionMedian; c.emission.activity.social = A.social; c.emission.activity.work = A.work;
  c.immune.protection = c.immune.protectionStaff = A.protection;
  c.transmission.closeShare = closeShare; c.transmission.G = at.G;
  // Lamps high on the walls: light path and dimming from OSLUV's Illuminate, for lamps angled down (the default) or pointed across the room.
  c.lamp.mount = 'wall'; c.lamp.wall = ILLUMINATE_WALL; c.lamp.across = ILLUMINATE_ACROSS;
  return c;
}

